import { Alert } from "@aibel365/devops-designsystem";
import axios from "axios";
import i18next from "i18next";

export function communicationFailedMiddleware(error: any) {
    if ((axios.isAxiosError(error) && error.code === "ERR_NETWORK") || error.code === "ERR_CANCELED") {
        console.error({
            title: i18next.t("global:noConnectionDialog.title"),
            description: i18next.t("global:noConnectionDialog.description"),
            content: <Alert data-color="warning">{i18next.t("global:noConnectionDialog.content")}</Alert>
        });
    }

    // msal issue, will happend if you type in wrong scope and end up in endless loop
    if (error.errorCode) {
        console.error({
            title: i18next.t("global:clientError.title"),
            description: i18next.t("global:clientError.status") + " (MSAL)",
            content: <Alert data-color="danger">{i18next.t("global:clientError.subtitle")}</Alert>
        });
    }
}

import type { RedirectRequest } from "@azure/msal-browser";
import type { InternalAxiosRequestConfig } from "axios";
import { getMsalInstance, getTokenResponse } from "../../auth";

/**
 * This middleware checks if there's an access token available in local storage,
 * and appends it to the request headers if available.
 *
 * @param config
 */
export async function injectBearerTokenMiddleware(config: InternalAxiosRequestConfig, request: RedirectRequest) {
    const msalInstance = await getMsalInstance();

    if (!msalInstance) return config;

    const account = msalInstance.getActiveAccount();
    if (!account) return config;

    const response = await getTokenResponse(msalInstance, { ...request, account });

    if (response == null) return config;

    if (response.accessToken) {
        config.headers["Authorization"] = `Bearer ${response.accessToken}`;
    }

    return config;
}

import { MutationCache, QueryCache, QueryClient } from "@tanstack/react-query";
import { communicationFailedMiddleware } from "./interceptors/communicationFailedMiddleware";

/**
 * A single instance of the QueryClient should be provided to the application's QueryClientProvider wrapper.
 * You can configure this client here, which can then be retrieved through the useQueryClient hook later.
 *
 * @see https://tanstack.com/query/latest/docs/react/reference/QueryClient
 */
export const queryClient = new QueryClient({
    queryCache: new QueryCache({
        onError: (error, _query) => {
            communicationFailedMiddleware(error);
        }
    }),
    mutationCache: new MutationCache({
        onError: (error, _variables, _context, mutation) => {
            if (mutation.options.onError) return;
            communicationFailedMiddleware(error);
        }
    }),
    defaultOptions: {
        queries: {
            retry: false
        }
    }
});

