import { Header } from "#/components";
import { getPublicConfig } from "#/integrations/aibel/functions/getConfig";
import { AibelApplicationProvider } from "#/integrations/aibel/providers/AibelApplicationProvider";
import { FooterBar } from "@aibel365/devops-designsystem";
import { TanStackDevtools } from "@tanstack/react-devtools";
import { formDevtoolsPlugin } from "@tanstack/react-form-devtools";
import type { QueryClient } from "@tanstack/react-query";
import { HeadContent, Scripts, createRootRouteWithContext } from "@tanstack/react-router";
import { TanStackRouterDevtoolsPanel } from "@tanstack/react-router-devtools";
import TanStackQueryDevtools from "../integrations/tanstack-query/devtools";
import TanStackQueryProvider from "../integrations/tanstack-query/root-provider";
import appCss from "../styles.css?url";

interface MyRouterContext {
    queryClient: QueryClient;
}

const THEME_INIT_SCRIPT = `(function(){try{var stored=window.localStorage.getItem('theme');var mode=(stored==='light'||stored==='dark'||stored==='auto')?stored:'auto';var prefersDark=window.matchMedia('(prefers-color-scheme: dark)').matches;var resolved=mode==='auto'?(prefersDark?'dark':'light'):mode;var root=document.documentElement;root.classList.remove('light','dark');root.classList.add(resolved);if(mode==='auto'){root.removeAttribute('data-theme')}else{root.setAttribute('data-theme',mode)}root.style.colorScheme=resolved;}catch(e){}})();`;

export const Route = createRootRouteWithContext<MyRouterContext>()({
    loader: async () => {
        // Fetch the server runtime config before rendering
        const config = await getPublicConfig();
        return { config };
    },
    head: ({ loaderData }) => ({
        meta: [
            {
                charSet: "utf-8"
            },
            {
                name: "viewport",
                content: "width=device-width, initial-scale=1"
            },
            {
                title: loaderData?.config.APP_DISPLAY_NAME
            }
        ],
        links: [
            {
                rel: "stylesheet",
                href: appCss
            }
        ]
    }),
    shellComponent: RootDocument
});

function RootDocument({ children }: { children: React.ReactNode }) {
    const year = new Date().getFullYear();
    const { config } = Route.useLoaderData();

    return (
        <html
            lang="en"
            suppressHydrationWarning
        >
            <head>
                <script dangerouslySetInnerHTML={{ __html: THEME_INIT_SCRIPT }} />
                <HeadContent />
            </head>
            <body className="font-sans antialiased wrap-anywhere selection:bg-[rgba(79,184,178,0.24)] h-screen overflow-hidden">
                <div className="grid grid-rows-[auto_1fr_auto] h-full">
                    <AibelApplicationProvider config={config}>
                        <TanStackQueryProvider>
                            <Header title={config.DISPLAY_NAME} />
                            {children}
                            <footer>
                                <FooterBar
                                    centeredContent={<p>&copy; {year} Aibel</p>}
                                    className="h-12"
                                />
                            </footer>
                            <TanStackDevtools
                                config={{
                                    position: "bottom-right"
                                }}
                                plugins={[
                                    {
                                        name: "Tanstack Router",
                                        render: <TanStackRouterDevtoolsPanel />
                                    },
                                    TanStackQueryDevtools,
                                    formDevtoolsPlugin()
                                ]}
                            />
                        </TanStackQueryProvider>
                    </AibelApplicationProvider>
                </div>
                <Scripts />
            </body>
        </html>
    );
}

